def style_fig(fig, title, height=470, legend=None):
    """One consistent look for every chart. The legend always sits
    *below* the plot with its own space, so it never overlaps title or axes."""
    if legend is None:
        legend = fig.layout.showlegend is not False and len(fig.data) > 1
    fig.update_layout(
        template="plotly_white",
        title=dict(text=title, x=0.02, xanchor="left", y=0.96, yanchor="top",
                   font=dict(size=18, color=HEAD, family="Playfair Display, Georgia, serif")),
        height=height,
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(family="DM Sans, Segoe UI, Roboto, sans-serif", color=TEXT, size=13),
        margin=dict(l=24, r=24, t=80, b=140 if legend else 44),
        showlegend=bool(legend),
        legend=dict(orientation="h", yanchor="top", y=-0.3, xanchor="center", x=0.5,
                    bgcolor="rgba(0,0,0,0)", title_text="", font=dict(color=TEXT, size=12)),
        hoverlabel=dict(bgcolor="#ffffff", bordercolor=AXIS, font_size=13, font_color=TEXT),
        uniformtext=dict(minsize=10, mode="hide"),
    )
    fig.update_xaxes(gridcolor=GRID, zeroline=False, linecolor=AXIS,
                     tickfont=dict(color=TEXT), title_font=dict(color=MUTED), automargin=True)
    fig.update_yaxes(gridcolor=GRID, zeroline=False, linecolor=AXIS,
                     tickfont=dict(color=TEXT), title_font=dict(color=MUTED), automargin=True)
    try:  # white gaps between bar segments + rounded corners (newer Plotly only)
        fig.update_traces(marker_line_color="#ffffff", marker_line_width=1.5, selector=dict(type="bar"))
        fig.update_traces(marker_cornerradius=6, selector=dict(type="bar"))
    except Exception:
        pass
    return fig


def show(fig):
    """Works on both old and new Streamlit versions."""
    try:
        st.plotly_chart(fig, width="stretch")
    except TypeError:
        st.plotly_chart(fig, use_container_width=True)


def show_df(d, **kw):
    try:
        st.dataframe(d, width="stretch", **kw)
    except TypeError:
        st.dataframe(d, use_container_width=True, **kw)


def callout(text):
    st.markdown(f'<div class="callout">{text}</div>', unsafe_allow_html=True)


def insight(text):
    st.markdown(f'<div class="insight">{text}</div>', unsafe_allow_html=True)


@st.cache_data(show_spinner="Loading satellite & respiratory data…")
def load_data(src):
    df = pd.read_csv(src)
    df["pathogen"] = df["pathogen"].replace(PATHOGEN_FIX)
    df["month"] = df["month"].astype(int)
    df["season"] = pd.Categorical(df["season"], categories=SEASONS, ordered=True)
    return df


# ── analysis functions (pure pandas, no Streamlit) ───────────
def build_monthly(df, months, pathogens):
    """One row per month: environment (constant within a month) + record count."""
    env = df.groupby("month")[ENV_COLS].mean()
    out = env.copy()
    out["season"] = df.groupby("month")["season"].first().astype(str)
    out["cases"] = (df[df["pathogen"].isin(pathogens)].groupby("month").size()
                    .reindex(env.index, fill_value=0))
    out = out.loc[out.index.isin(months)].reset_index()
    out["Month_Name"] = out["month"].map(MONTHS)
    return out


def season_means(m):
    order = [s for s in SEASONS if s in set(m["season"])]
    g = m.groupby("season")[ENV_COLS].mean().reindex(order)
    g["cases"] = m.groupby("season")["cases"].sum().reindex(order)
    return g


def dominance_table(sm, method, annual, who):
    """Season × pollutant score. Dominant pollutant = highest score in each row."""
    pol = sm[POLLUTANTS]
    if method.startswith("WHO"):
        return pol / pd.Series(who)[POLLUTANTS]
    return pol / annual[POLLUTANTS]


def corr_p(x, y, method):
    x_values: np.ndarray = np.asarray(x, dtype=np.float64)
    y_values: np.ndarray = np.asarray(y, dtype=np.float64)
    if len(x_values) < 4 or np.std(x_values) == 0 or np.std(y_values) == 0:
        return np.nan, np.nan
    if stats is not None:
        result = stats.spearmanr(x_values, y_values) if method == "Spearman" else stats.pearsonr(x_values, y_values)
        return float(np.asarray(result[0]).item()), float(np.asarray(result[1]).item())
    if method == "Spearman":
        x_values = pd.Series(x_values).rank().to_numpy(dtype=np.float64)
        y_values = pd.Series(y_values).rank().to_numpy(dtype=np.float64)
    return float(np.corrcoef(x_values, y_values)[0, 1]), np.nan


def stars(p):
    return "" if pd.isna(p) else "**" if p < 0.01 else "*" if p < 0.05 else ""


def strength(r):
    a = abs(r)
    return "very strong" if a >= 0.8 else "strong" if a >= 0.6 else "moderate" if a >= 0.4 else "weak"


